import { test, expect } from '@playwright/test';

test.describe('Form Data Persistence on Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should persist form data when navigating away and returning', async ({ page }) => {
    // Fill out the form using getByLabel
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('john.doe@example.com');

    const messageInput = page.getByLabel('Message');
    await messageInput.fill('This is a test message');

    // Submit the form
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Navigate away from the form
    await page.goto('/dashboard');

    // Verify form data is still present on the dashboard
    const dashboardForm = page.getByLabel('Contact Form');
    await expect(dashboardForm).toBeVisible();

    const nameDisplay = page.getByText('John Doe');
    await expect(nameDisplay).toBeVisible();

    const emailDisplay = page.getByText('john.doe@example.com');
    await expect(emailDisplay).toBeVisible();

    // Return to the form
    await page.goto('/form');

    // Verify form data is still present
    const nameInput = page.getByLabel('Full Name');
    await expect(nameInput).toHaveValue('John Doe');

    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toHaveValue('john.doe@example.com');

    // Verify success message is still visible
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();
  });

  test('should not persist form data when navigating away and returning with invalid data', async ({ page }) => {
    // Fill out the form using getByLabel
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('Jane Smith');

    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('jane.smith@example.com');

    // Submit the form
    const submitButton = page.getByRole('button', { name: 'Submit' });
    await submitButton.click();

    // Verify success message appears
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Navigate away from the form
    await page.goto('/dashboard');

    // Return to the form with invalid data
    await page.goto('/form');

    // Verify form data is cleared
    const nameInput = page.getByLabel('Full Name');
    await expect(nameInput).toHaveValue('');

    const emailInput = page.getByLabel('Email Address');
    await expect(emailInput).toHaveValue('');

    // Verify success message is no longer visible
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).not.toBeVisible();

    // Verify error message appears
    const errorMessage = page.getByText('Please fill out all fields');
    await expect(errorMessage).toBeVisible();
  });
});
